namespace Dataphyre\Panel;

/** Server-owned remote mutation endpoint, capability, authentication, retry, and circuit policy. */
final class PanelHttpDataMutationDefinition implements \JsonSerializable {
	private readonly string $name;private readonly string $endpoint;private readonly int $maxRequestBytes;private readonly int $maxResponseBytes;private readonly int $timeoutMilliseconds;private readonly int $maxAttempts;private readonly int $retryBackoffMilliseconds;private readonly int $circuitFailureThreshold;private readonly int $circuitOpenMilliseconds;private readonly string $fingerprint;
	/** @var list<int> */private readonly array $retryStatuses;
	/** @param array<string,mixed> $options */
	public function __construct(string $name,string $endpoint,private readonly PanelHttpDataMutationCapabilityPin $capabilityPin,private readonly PanelHttpDataMutationAuthenticator $authenticator,array $options=[]){
		$allowed=['max_request_bytes','max_response_bytes','timeout_ms','max_attempts','retry_statuses','retry_backoff_ms','circuit_failure_threshold','circuit_open_ms'];$unknown=array_values(array_diff(array_keys($options),$allowed));if($unknown!==[]){throw new \InvalidArgumentException('Unknown remote mutation option: '.(string)$unknown[0]);}
		$this->name=PanelHttpDataSourceValue::identifier($name,'Remote mutation source name',64);$this->endpoint=self::normalizeEndpoint($endpoint);
		$this->maxRequestBytes=self::integer($options,'max_request_bytes',1048576,4096,4194304);$this->maxResponseBytes=self::integer($options,'max_response_bytes',2097152,4096,8388608);$this->timeoutMilliseconds=self::integer($options,'timeout_ms',10000,50,120000);$this->maxAttempts=self::integer($options,'max_attempts',2,1,3);$this->retryBackoffMilliseconds=self::integer($options,'retry_backoff_ms',50,0,2000);$this->circuitFailureThreshold=self::integer($options,'circuit_failure_threshold',5,1,20);$this->circuitOpenMilliseconds=self::integer($options,'circuit_open_ms',30000,100,300000);
		$statuses=$options['retry_statuses']??[408,425,429,500,502,503,504];if(!is_array($statuses)||!array_is_list($statuses)||count($statuses)>7){throw new \InvalidArgumentException('Remote mutation retry_statuses must be a bounded list.');}$retry=[];foreach($statuses as$status){if(!is_int($status)||!in_array($status,[408,425,429,500,502,503,504],true)){throw new \InvalidArgumentException('Remote mutation retry_statuses contains an unsupported status.');}$retry[$status]=true;}$retryStatuses=array_keys($retry);sort($retryStatuses,SORT_NUMERIC);$this->retryStatuses=$retryStatuses;
		$safe=['name'=>$this->name,'capability'=>$capabilityPin->fingerprint(),'authenticator'=>$authenticator->jsonSerialize(),'request'=>$this->maxRequestBytes,'response'=>$this->maxResponseBytes,'timeout'=>$this->timeoutMilliseconds,'attempts'=>$this->maxAttempts,'statuses'=>$this->retryStatuses,'backoff'=>$this->retryBackoffMilliseconds,'circuit_failures'=>$this->circuitFailureThreshold,'circuit_open'=>$this->circuitOpenMilliseconds];$this->fingerprint=$authenticator->bindingFingerprint($this->endpoint."\0".PanelHttpDataSourceValue::canonical($safe));
	}
	public function name():string{return$this->name;}public function endpoint():string{return$this->endpoint;}public function capabilityPin():PanelHttpDataMutationCapabilityPin{return$this->capabilityPin;}public function authenticator():PanelHttpDataMutationAuthenticator{return$this->authenticator;}public function maxRequestBytes():int{return$this->maxRequestBytes;}public function maxResponseBytes():int{return$this->maxResponseBytes;}public function timeoutMilliseconds():int{return$this->timeoutMilliseconds;}public function maxAttempts():int{return$this->maxAttempts;}/** @return list<int> */public function retryStatuses():array{return$this->retryStatuses;}public function retryBackoffMilliseconds():int{return$this->retryBackoffMilliseconds;}public function circuitFailureThreshold():int{return$this->circuitFailureThreshold;}public function circuitOpenMilliseconds():int{return$this->circuitOpenMilliseconds;}public function fingerprint():string{return$this->fingerprint;}
	/** @return array<string,mixed> */public function jsonSerialize():array{return['type'=>'panel_http_data_mutation_definition','version'=>1,'name'=>$this->name,'definition_fingerprint'=>$this->fingerprint,'endpoint'=>['configured'=>true,'serialized'=>false,'request_selectable'=>false],'capability_pin'=>$this->capabilityPin->jsonSerialize(),'authenticator'=>$this->authenticator->jsonSerialize(),'bounds'=>['max_request_bytes'=>$this->maxRequestBytes,'max_response_bytes'=>$this->maxResponseBytes,'timeout_ms'=>$this->timeoutMilliseconds],'retry'=>['idempotent_mutations_only'=>true,'max_attempts'=>$this->maxAttempts,'statuses'=>$this->retryStatuses,'base_backoff_ms'=>$this->retryBackoffMilliseconds,'sleep_owner'=>'injected_runtime'],'circuit'=>['failure_threshold'=>$this->circuitFailureThreshold,'open_ms'=>$this->circuitOpenMilliseconds]];}
	private static function integer(array $options,string $key,int $default,int $minimum,int $maximum):int{$value=$options[$key]??$default;if(!is_int($value)||$value<$minimum||$value>$maximum){throw new \InvalidArgumentException("Remote mutation {$key} must be between {$minimum} and {$maximum}.");}return$value;}
	private static function normalizeEndpoint(string $endpoint):string{$endpoint=PanelHttpDataSourceValue::text($endpoint,'Remote mutation endpoint',2048);$parts=parse_url($endpoint);if(!is_array($parts)||!in_array(strtolower((string)($parts['scheme']??'')),['http','https'],true)||trim((string)($parts['host']??''))===''||isset($parts['user'])||isset($parts['pass'])||isset($parts['query'])||isset($parts['fragment'])){throw new \InvalidArgumentException('Remote mutation endpoints must be absolute HTTP(S) URLs without credentials, query, or fragment components.');}return$endpoint;}
}
